export function getHRMLAProfile(acNo: number): MLAProfile | undefined {
  return HR_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getHRMLAsByParty(party: string): MLAProfile[] {
  return HR_MLA_PROFILES.filter(p => p.party === party);
}

export function getHRFemaleMLAs(): MLAProfile[] {
  return HR_MLA_PROFILES.filter(p => p.gender === 'F');
}
